// ===== 哔咔漫画 自包含库 (v84) =====
// 作用域铁律：jsLib 在独立 ScriptBindings 求值，只有函数定义被 chainTo 共享；
// source/java/baseUrl/result 在此不存在 => 一律参数注入 (SRC, JV)，禁止裸引用。
// 本次全部改名（picab_ -> picac_ / PICAB_ -> PICAC_），规避 Rhino SharedJsScope 编译缓存。
var PICA = {
  API_KEY: "C69BAF41DA5ABD1FFEDC6D2FEA56B",
  SECRET: "~d}$Q7$eIni=V)9" + String.fromCharCode(92) + "RK/P.RM4;9[7|@/CA}b~OW!3?EV" + String.fromCharCode(96, 58, 60, 62) + "M7pddUBL5n|0/*Cn",
  BASE: "https://picaapi.picacomic.com/",
  DNS_POOL: ["172.67.194.19", "172.67.80.1", "104.21.235.3",
             "104.21.235.4", "104.21.91.145", "104.19.53.76",
             "104.21.80.1", "104.21.81.1", "104.16.0.1", "104.17.0.1"],
  INIT_URL: "http://68.183.234.72/init",
  MIRROR: "https://s3.go2778.com"
};

function picac_hash(s) {
  var h = 0;
  s = String(s || "");
  for (var i = 0; i < s.length; i++) {
    h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  }
  return Math.abs(h);
}

function picac_bytes(str) {
  return new Packages.java.lang.String(str).getBytes("UTF-8");
}

function picac_hmac(raw, key) {
  var m = Packages.javax.crypto.Mac.getInstance("HmacSHA256");
  m.init(new Packages.javax.crypto.spec.SecretKeySpec(picac_bytes(key), "HmacSHA256"));
  var b = m.doFinal(picac_bytes(raw));
  var s = "";
  for (var i = 0; i < b.length; i++) {
    var x = b[i] & 0xff;
    s += (x < 16 ? "0" : "") + x.toString(16);
  }
  return s;
}

function picac_nonce() {
  var s = "";
  for (var i = 0; i < 32; i++) {
    s += "0123456789abcdef".charAt(Math.floor(Math.random() * 16));
  }
  return s;
}

function picac_token(SRC) {
  try {
    var h = String(SRC.getLoginHeader() || "");
    if (h && h !== "null") {
      var m = h.match(new RegExp('"authorization"\\s*:\\s*"([^"]+)"'));
      if (m) { return m[1]; }
      return h;
    }
  } catch (e0) {}
  try { return String(SRC.get("picab_token") || ""); } catch (e1) { return ""; }
}

function picac_official(SRC) {
  try { return String(SRC.get("picab_official_ips") || ""); } catch (e0) { return ""; }
}

function picac_pool(SRC) {
  var p = "";
  try { p = String(SRC.get("picab_pool") || ""); } catch (e0) {}
  if (p === "none") { return ""; }
  if (p) { return p; }
  return PICA.DNS_POOL.join(",");
}

function picac_stationName(idx) {
  return ({ "0": "官方init", "1": "Cloudflare", "2": "系统DNS直连" })[String(idx)] || "未知";
}

function picac_currentStation(SRC) {
  try { return String(SRC.get("picab_station") || "1"); } catch (e0) { return "1"; }
}

function picac_coverMode(SRC) {
  try {
    var m = String(SRC.get("picab_cover_mode") || "ip");
    return (m === "dns" || m === "mirror") ? m : "ip";
  } catch (e0) { return "ip"; }
}

function picac_buildPool(station, official) {
  var out = [];
  function add(ip) {
    ip = String(ip || "").trim();
    if (ip && ip.indexOf(".") > 0 && out.indexOf(ip) < 0) { out.push(ip); }
  }
  if (station === "0") {
    String(official || "").split(",").forEach(add);
    PICA.DNS_POOL.forEach(add);
  } else if (station === "1") {
    PICA.DNS_POOL.forEach(add);
  } else {
    return "none";
  }
  return out.join(",");
}

function picac_headers(path, method, SRC, JV) {
  var ts = String(Math.floor(Date.now() / 1000));
  var nonce = picac_nonce();
  var raw = (path + ts + nonce + method + PICA.API_KEY).toLowerCase();
  var sig = picac_hmac(raw, PICA.SECRET);
  var h = {
    "User-Agent": "okhttp/3.8.1",
    "accept": "application/vnd.picacomic.com.v1+json",
    "api-key": PICA.API_KEY,
    "app-channel": "2",
    "app-version": "2.2.1.2.3.3",
    "app-uuid": "defaultUuid",
    "app-platform": "android",
    "app-build-version": "44",
    "image-quality": "original",
    "time": ts,
    "nonce": nonce,
    "signature": sig
  };
  var tk = picac_token(SRC);
  if (tk && tk !== "null" && tk !== "") { h["authorization"] = tk; }
  return h;
}

function picac_opt(path, opt, SRC, JV) {
  opt = opt || {};
  opt.headers = picac_headers(path, opt.method || "GET", SRC, JV);
  if ((opt.method || "GET") === "POST") {
    opt.headers["Content-Type"] = "application/json; charset=UTF-8";
  }
  var dp = picac_pool(SRC);
  if (dp && !opt.dnsIp) { opt.dnsIp = dp; }
  if (!opt.retry) { opt.retry = 4; }
  if (!opt.timeout) { opt.timeout = 25000; }
  return PICA.BASE + path + "," + JSON.stringify(opt);
}

function picac_get(path, SRC, JV) {
  var last = "";
  for (var i = 0; i < 3; i++) {
    last = String(JV.ajax(picac_opt(path, { method: "GET" }, SRC, JV)) || "");
    if (last.charAt(0) === "{") { return last; }
    if (i < 2) {
      try { Packages.java.lang.Thread.sleep(1500); } catch (e0) {}
    }
  }
  return last;
}

function picac_post(path, bodyObj, SRC, JV) {
  var last = "";
  for (var i = 0; i < 3; i++) {
    last = String(JV.ajax(picac_opt(path, { method: "POST", body: JSON.stringify(bodyObj) }, SRC, JV)) || "");
    if (last.charAt(0) === "{") { return last; }
    if (i < 2) {
      try { Packages.java.lang.Thread.sleep(1500); } catch (e0) {}
    }
  }
  return last;
}
