// 登录：只有 loginUrl 的 login() 绑定 result（= 登录面板各输入）
function login() {
  var u = String(result["账号"] || "").replace(/^\s+|\s+$/g, "");
  var p = String(result["密码"] || "").replace(/^\s+|\s+$/g, "");
  if (!u) { java.longToast("请填写账号"); return; }
  if (!p) { java.longToast("请填写密码"); return; }
  var msg = "";
  try {
    var path = "auth/sign-in";
    var h = picac_headers(path, "POST", source, java);
    h["Content-Type"] = "application/json; charset=UTF-8";
    var opt = { method: "POST", body: JSON.stringify({ email: u, password: p }),
                headers: h, timeout: 30000, retry: 2 };
    var dp = picac_pool(source);
    if (dp) { opt.dnsIp = dp; }
    var resp = java.ajax("https://picaapi.picacomic.com/" + path + "," + JSON.stringify(opt));
    var txt = String(resp || "");
    var jo = null;
    try { jo = JSON.parse(txt); } catch (e0) {}
    if (jo && jo.code === 200 && jo.data && jo.data.token) {
      source.putLoginHeader(jo.data.token);
      try { source.put("picab_token", jo.data.token); } catch (e5) {}
      try { source.refreshExplore(); } catch (e6) {}
      msg = "✅ 登录成功: " + u;
    } else {
      msg = "❌ 登录失败: " + (jo && jo.message ? jo.message : txt.substring(0, 80));
    }
  } catch (e) { msg = "登录异常: " + e; }
  try { java.upLoginData({ "登录状态": msg }); } catch (e1) {}
  try { java.toast(msg); } catch (e2) {}
  try { java.longToast(msg); } catch (e3) {}
}
